#!/usr/bin/env node
// The bundled Flutter SVGs define the supported cross-framework artwork set.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const assets = fs.readdirSync(path.join(root, 'packages/flutter/assets/twemoji'))
  .filter(name => name.endsWith('.svg')).map(name => name.slice(0, -4)).sort()
fs.writeFileSync(path.join(root, 'packages/emoji-picker/src/emoji-artwork.generated.ts'),
  '// Generated by scripts/generate-emoji-artwork.mjs from the bundled Twemoji SVGs.\n' +
  `export const EMOJI_ARTWORK_KEYS: ReadonlySet<string> = new Set(${JSON.stringify(assets, null, 2)})\n`)
